const documents = $input.all().map(item => item.json.document);

const policies = documents.filter(
  doc => doc?.policy_id === 'doc-landscape-retrieval-quality'
);
const baselines = documents.filter(doc => doc?.baseline_id);

if (
  documents.length !== 2 ||
  policies.length !== 1 ||
  baselines.length !== 1
) {
  throw new Error('Expected exactly one policy and one baseline.');
}

const policy = policies[0];
const baseline = baselines[0];

if (policy.schema_version !== 1 || baseline.schema_version !== 1) {
  throw new Error('Unsupported policy or baseline schema version.');
}

if (
  !Number.isInteger(policy.policy_version) ||
  policy.policy_version < 1 ||
  baseline.policy_version !== policy.policy_version
) {
  throw new Error('Invalid or mismatched policy versions.');
}

if (
  policy.activation?.configuration_verified !== true ||
  baseline.configuration_evidence?.verification_status !==
    'recorded_settings_match'
) {
  throw new Error('Baseline configuration verification is incomplete.');
}

return [{ json: { policy, baseline } }];

// n8n Code node: Compare retrieval quality
// Language: JavaScript. Mode: Run Once for All Items.
// Input: Evaluation status -> Succeeded (the operations job envelope).
// Reads this execution's saved Prepare quality rules and Content changed outputs.
// No network requests, external packages, baseline writes, or Jira actions.

function compareQuality(job, snapshot, context = {}) {
  const reasons = [];
  const problems = [];
  const reviews = [];
  const breaches = [];
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  const missing = value => value === undefined || value === null;
  const at = (value, path) => path.split('.').reduce((v, key) => v?.[key], value);
  const problem = (code, detail) => problems.push({ code, detail });
  const review = (code, detail) => reviews.push({ code, detail });
  const policy = snapshot?.policy;
  const baseline = snapshot?.baseline;
  const report = object(job?.result) ? job.result : null;
  const record = {
    outcome: null,
    indexing_job_id: context.indexing_job_id ?? null,
    evaluation_job_id: job?.job_id ?? null,
    n8n_execution_id: context.n8n_execution_id ?? null,
    policy_version: policy?.policy_version ?? null,
    baseline_id: baseline?.baseline_id ?? null,
    dataset_version: report?.dataset_version ?? null,
    report_paths: report?.report_paths ?? null,
    known_failed_case_ids: baseline?.known_failed_case_ids ?? [],
    observed_known_failed_case_ids: [],
    resolved_known_failed_case_ids: [],
    observed_failed_case_ids: null,
    new_failed_case_ids: [],
    metrics: {},
    regression_route_eligible: false,
    reasons,
  };

  function finish(outcome) {
    record.outcome = outcome;
    reasons.unshift(...problems, ...reviews, ...breaches);
    for (const field of ['indexing_job_id', 'evaluation_job_id', 'n8n_execution_id', 'policy_version', 'dataset_version', 'report_paths']) {
      if (missing(record[field])) reasons.push({ code: 'context_unavailable', field, detail: `${field} was unavailable; retained as null.` });
    }
    if (outcome === 'passed') reasons.push({ code: 'all_checks_passed', detail: 'All comparison rules passed. Existing known failures remain visible.' });
    return record;
  }

  // Decimal arithmetic on number.toString(), without binary subtraction.
  // BigInt stays internal; output contains only JSON-compatible values.
  function decimal(value) {
    const [mantissa, exponent = '0'] = String(value).toLowerCase().split('e');
    const [whole, fraction = ''] = mantissa.split('.');
    let coefficient = BigInt(whole + fraction);
    let scale = fraction.length - Number(exponent);
    if (scale < 0) { coefficient *= 10n ** BigInt(-scale); scale = 0; }
    return { coefficient, scale };
  }
  function subtract(a, b) {
    const scale = Math.max(a.scale, b.scale);
    return { coefficient: a.coefficient * 10n ** BigInt(scale - a.scale) - b.coefficient * 10n ** BigInt(scale - b.scale), scale };
  }
  function compare(a, b) {
    const difference = subtract(a, b).coefficient;
    return difference < 0n ? -1 : difference > 0n ? 1 : 0;
  }
  function decimalText(value) {
    const sign = value.coefficient < 0n ? '-' : '';
    const digits = (value.coefficient < 0n ? -value.coefficient : value.coefficient).toString().padStart(value.scale + 1, '0');
    return sign + (value.scale ? digits.slice(0, -value.scale) + '.' + digits.slice(-value.scale) : digits);
  }
  const metricNames = ['mean_precision_at_k', 'mean_recall_at_k', 'mean_reciprocal_rank', 'hit_rate_at_k', 'unanswerable_accuracy'];
  const validMetric = value => typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 1;
  const validIds = value => Array.isArray(value) && value.every(id => typeof id === 'string' && id.length > 0) && new Set(value).size === value.length;

  if (!object(policy) || !object(baseline)) {
    problem('policy_load_failed', 'The saved execution must contain both policy and baseline objects.');
    return finish('operational_failure');
  }
  if (policy.schema_version !== 1 || baseline.schema_version !== 1 || policy.policy_version !== 1 || baseline.policy_version !== policy.policy_version) {
    problem('unsupported_version', 'This comparator supports schema 1 and policy 1 with matching baseline policy_version.');
  }
  if (policy.activation?.configuration_verified !== true || baseline.configuration_evidence?.verification_status !== 'recorded_settings_match') {
    problem('configuration_not_verified', 'Baseline configuration verification is incomplete.');
  }
  if (!validIds(baseline.known_failed_case_ids)) problem('invalid_baseline', 'known_failed_case_ids must be a unique list of nonempty strings.');
  if (!Array.isArray(policy.comparability?.required_equal_fields) || !policy.comparability.required_equal_fields.every(path => typeof path === 'string' && path.length > 0)) {
    problem('invalid_policy', 'Comparability fields are missing or invalid.');
  }
  if (!Array.isArray(policy.completeness?.required_metrics) || metricNames.some(name => !policy.completeness.required_metrics.includes(name)) || policy.completeness.required_metrics.length !== metricNames.length) {
    problem('invalid_policy', 'The required metric list must match the supported policy 1 metrics.');
  }
  for (const name of metricNames) {
    const rule = policy.metric_rules?.[name];
    if (!validMetric(rule?.minimum) || !validMetric(rule?.maximum_decline) || !validMetric(baseline.summary?.[name])) {
      problem('invalid_policy_or_baseline', `Invalid rule or baseline metric: ${name}.`);
    }
  }
  if (problems.length) return finish('operational_failure');
  if (!object(job) || job.operation !== 'evaluate_retrieval' || job.status !== 'succeeded' || !report || job.error != null) {
    problem('evaluation_not_successful', 'Expected a succeeded evaluate_retrieval job with an object result and no job error.');
    return finish('operational_failure');
  }
  if (!object(report.summary)) {
    if (missing(report.summary)) review('summary_missing', 'Evaluation summary is unavailable.');
    else problem('malformed_summary', 'Evaluation summary must be an object.');
    return finish(problems.length ? 'operational_failure' : 'needs_review');
  }

  const observed = { ...report, k: report.k ?? report.retrieval_configuration?.k };
  for (const path of policy.comparability.required_equal_fields) {
    const expected = at(baseline, path);
    const actual = at(observed, path);
    if (missing(expected)) problem('invalid_baseline', `Baseline comparison field is missing: ${path}.`);
    else if (missing(actual)) review('comparison_metadata_missing', `Current report is missing ${path}.`);
    else if (actual !== expected) review('comparison_mismatch', `${path} differs from the fixed baseline. Expected ${JSON.stringify(expected)}; observed ${JSON.stringify(actual)}.`);
  }
  if (!missing(report.retrieval_configuration) && !object(report.retrieval_configuration)) problem('malformed_configuration', 'retrieval_configuration must be an object.');
  if (!missing(report.k) && !missing(report.retrieval_configuration?.k) && report.k !== report.retrieval_configuration.k) problem('inconsistent_k', 'Report k and retrieval_configuration.k disagree.');

  const summary = report.summary;
  const countFields = ['total_cases', 'answerable_cases', 'unanswerable_cases', 'precision_evaluable_cases'];
  for (const field of countFields) {
    if (missing(summary[field])) review('count_missing', `summary.${field} is unavailable.`);
    else if (!Number.isSafeInteger(summary[field]) || summary[field] < 0) problem('invalid_count', `summary.${field} must be a nonnegative integer.`);
  }
  const hasCounts = countFields.every(field => Number.isSafeInteger(summary[field]) && summary[field] >= 0);
  if (hasCounts) {
    if (summary.total_cases !== summary.answerable_cases + summary.unanswerable_cases) problem('inconsistent_counts', 'Answerable and unanswerable counts do not add up to total_cases.');
    if (summary.precision_evaluable_cases > summary.answerable_cases) problem('inconsistent_counts', 'Precision coverage exceeds answerable case count.');
    else if (summary.precision_evaluable_cases < summary.answerable_cases) review('incomplete_precision_coverage', `${summary.precision_evaluable_cases}/${summary.answerable_cases} answerable cases have complete precision judgments.`);
  }
  for (const name of metricNames) {
    if (missing(summary[name])) review('metric_unavailable', `summary.${name} is missing or null.`);
    else if (!validMetric(summary[name])) problem('invalid_metric', `summary.${name} must be a finite number between 0 and 1; booleans are invalid.`);
  }

  let failedIds = null;
  let casesFailed = null;
  if (!missing(report.failed_case_ids)) {
    if (!validIds(report.failed_case_ids)) problem('invalid_failure_evidence', 'failed_case_ids must be a unique list of nonempty strings.');
    else failedIds = report.failed_case_ids;
  }
  if (!missing(report.cases)) {
    if (!Array.isArray(report.cases) || report.cases.some(c => !object(c) || typeof c.case_id !== 'string' || !c.case_id || typeof c.passed !== 'boolean') || new Set(report.cases.map(c => c.case_id)).size !== report.cases.length) {
      problem('invalid_case_evidence', 'Cases must have unique case_id values and boolean passed values.');
    } else if (Number.isSafeInteger(summary.total_cases) && report.cases.length !== summary.total_cases) {
      problem('inconsistent_case_count', 'The case outcome list is not complete.');
    } else {
      casesFailed = report.cases.filter(c => !c.passed).map(c => c.case_id);
      if (failedIds && JSON.stringify([...failedIds].sort()) !== JSON.stringify([...casesFailed].sort())) problem('inconsistent_failures', 'failed_case_ids disagrees with case outcomes.');
      if (failedIds === null) failedIds = casesFailed;
    }
  }
  if (failedIds === null) review('failure_evidence_missing', 'Neither an explicit failed_case_ids list nor complete case outcomes are available.');
  if (failedIds !== null) {
    record.observed_failed_case_ids = [...failedIds];
    if (Number.isSafeInteger(summary.total_cases) && failedIds.length > summary.total_cases) problem('inconsistent_failures', 'There are more failed IDs than total cases.');
    if (!missing(summary.overall_success_rate)) {
      if (!validMetric(summary.overall_success_rate)) problem('invalid_metric', 'overall_success_rate is malformed.');
      else if (summary.total_cases > 0 && Math.abs(summary.overall_success_rate - (summary.total_cases - failedIds.length) / summary.total_cases) > 1e-12) problem('inconsistent_outcomes', 'overall_success_rate disagrees with failed case count.');
    }
  }
  if (problems.length) return finish('operational_failure');
  // An incomparable or incompletely judged report cannot confirm regression.
  if (reviews.length) return finish('needs_review');

  const known = new Set(baseline.known_failed_case_ids);
  const failed = new Set(failedIds);
  record.observed_known_failed_case_ids = failedIds.filter(id => known.has(id));
  record.resolved_known_failed_case_ids = baseline.known_failed_case_ids.filter(id => !failed.has(id));
  record.new_failed_case_ids = failedIds.filter(id => !known.has(id));
  for (const case_id of record.new_failed_case_ids) {
    breaches.push({ code: 'new_failed_case', case_id, reason: 'This failed case is not in the fixed baseline known-failure list.' });
  }
  for (const name of metricNames) {
    const rule = policy.metric_rules[name];
    const baselineValue = baseline.summary[name];
    const actual = summary[name];
    const decline = subtract(decimal(baselineValue), decimal(actual));
    const minimumPassed = compare(decimal(actual), decimal(rule.minimum)) >= 0;
    const declinePassed = compare(decline, decimal(rule.maximum_decline)) <= 0;
    record.metrics[name] = {
      baseline: baselineValue, observed: actual, minimum: rule.minimum,
      decline_limit: rule.maximum_decline,
      decline: decimalText(decline),
      minimum_passed: minimumPassed, decline_passed: declinePassed,
    };
    const detail = { metric: name, baseline: baselineValue, observed: actual, minimum: rule.minimum, decline_limit: rule.maximum_decline };
    if (!minimumPassed) breaches.push({ code: 'minimum_breached', ...detail, breached_rule: 'minimum' });
    if (!declinePassed) breaches.push({ code: 'maximum_decline_breached', ...detail, breached_rule: 'maximum_decline' });
  }
  record.regression_route_eligible = breaches.some(reason => policy.planned_regression_route.qualifying_reasons.includes(reason.code));
  return finish(breaches.length ? 'quality_failed' : 'passed');
}

const inputItems = $input.all();
if (inputItems.length !== 1) throw new Error('Compare retrieval quality expects exactly one evaluation job.');
const job = inputItems[0].json;
let snapshot = null;
let indexingJobId = null;
try { snapshot = $('Prepare quality rules').first().json; } catch (_) { /* Report missing snapshot as an operational failure. */ }
try { indexingJobId = $('Content changed').first().json.job_id ?? null; } catch (_) { /* Preserve null if context is unavailable. */ }
const quality = compareQuality(job, snapshot, {
  indexing_job_id: indexingJobId,
  n8n_execution_id: $execution.id ?? null,
});
return [{ json: { ...job, quality } }];

const evaluation = $('Compare retrieval quality').first().json;
const issue = $('Get existing regression').first().json;
const jobId = evaluation.quality?.evaluation_job_id;

if (typeof jobId !== 'string' || !jobId.trim()) {
  throw new Error('Evaluation job ID is missing.');
}

if (evaluation.quality?.outcome !== 'quality_failed' ||
    evaluation.quality?.regression_route_eligible !== true) {
  throw new Error('Expected a confirmed regression.');
}

if (typeof issue.key !== 'string' ||
    !Object.prototype.hasOwnProperty.call(issue.fields ?? {}, 'description')) {
  throw new Error('Ticket key or description field is missing.');
}

const items = $input.all().map(item => item.json);
const emptyResult = items.length === 1 &&
  Object.keys(items[0]).length === 0;
const comments = emptyResult ? [] : items;

if (comments.some(comment =>
  typeof comment.id !== 'string' ||
  !Object.prototype.hasOwnProperty.call(comment, 'body'))) {
  throw new Error('Unexpected comment data. Check the comments node output.');
}

const containsJob = body => JSON.stringify(body ?? '').includes(jobId);
const inDescription = containsJob(issue.fields.description);
const matchingCommentIds = comments
  .filter(comment => containsJob(comment.body))
  .map(comment => comment.id);

return [{
  json: {
    ...evaluation,
    jira_issue_key: issue.key,
    job_already_recorded: inDescription || matchingCommentIds.length > 0,
    job_recorded_in_description: inDescription,
    matching_comment_ids: matchingCommentIds,
  },
}];

const evaluation = $('Compare retrieval quality').first().json;
const response = $input.first().json;
const issueKey = response.key ??
  $('Find open regression').first().json.key;

if (!issueKey || !evaluation.quality) {
  throw new Error('Jira issue key or evaluation evidence is missing.');
}

return [{
  json: {
    ...evaluation,
    jira_issue_key: issueKey,
    jira_action: response.key ? 'issue_created' : 'comment_added',
    jira_response_id: response.id ?? null,
  },
}];
